policyExcerpt.text:
"risk_tier": "high",
"fail_mode": "fail_closed",
"thresholds": {
  "privacy": {
    "routine":  { "warn": 0.10, "block": 0.30 },   // generate_text, draft_email
    "elevated": { "warn": 0.10, "block": 0.25 },   // send_email, update_crm
    "severe":   { "warn": 0.05, "block": 0.15 }    // delete_record, execute_payment
  }
},
"mandatory_human_review_actions": ["send_email", "update_crm", "delete_record", "execute_payment"],
"max_session_exposure": 0.5,
"pii_handling": "block",
"latency_budget_ms": 1000
